printf '%s  %s\n' '6310f52669a47c76d219ba52e81ad87c7236d091de873e0699a0197b0e4dc6da' "$STAGE/feature.tar.gz" | sha256sum -c - >/dev/null
tar -C "$STAGE/installer" -xzf "$STAGE/feature.tar.gz"
touch "$STAGE/source/.xclip-production-staging"
"$NODE" "$STAGE/installer/install.cjs" "$STAGE/source"
LIVE="$LIVE" "$NODE" --env-file="$LIVE/.env.production" <<'JS'
const path=require('path'),os=require('os');
const state=process.env.XCLIP_DOWNLOAD_STATE_DIR||path.join(os.homedir(),'.xclip-download');
if(!path.isAbsolute(state))throw Error('DOWNLOAD_STATE_DIR_MUST_BE_ABSOLUTE; live unchanged');
const normalized=path.resolve(state),live=path.resolve(process.env.LIVE);
if(normalized===live||normalized.startsWith(live+path.sep))throw Error('DOWNLOAD_STATE_DIR_INSIDE_RUNTIME; live unchanged. Preserve state outside runtime before deployment.');
const authorDirectory=process.env.XCLIP_AUTHOR_STATE_DIR||path.join(os.homedir(),'.xclip-author-status');
if(!path.isAbsolute(authorDirectory)||path.resolve(authorDirectory)===live||path.resolve(authorDirectory).startsWith(live+path.sep))throw Error('AUTHOR_STATE_DIR_MUST_BE_DURABLE; public unchanged');
const freeDir=process.env.XCLIP_FREE_CURATED_STATE_DIR||path.join(os.homedir(),'.xclip-free-curated');
if(!path.isAbsolute(freeDir)||path.resolve(freeDir)===live||path.resolve(freeDir).startsWith(live+path.sep))throw Error('FREE_CURATED_STATE_DIR_MUST_BE_DURABLE');
const feed=process.env.XCLIP_RANKING_FEED_STATE_DIR||path.join(os.homedir(),'.xclip-ranking-feed');if(!path.isAbsolute(feed)||path.resolve(feed)===live||path.resolve(feed).startsWith(live+path.sep))throw Error('RANKING_STATE_MUST_BE_DURABLE');
console.log('DURABLE_DOWNLOAD_STATE_OK; no secret values printed');
JS
cp "$LIVE/.env.production" "$STAGE/source/.env.production"
chmod 600 "$STAGE/source/.env.production"
cd "$STAGE/source"
# Matching existing standalone configuration is preserved.
"$NODE" -e 'const fs=require("fs");const f=["next.config.ts","next.config.js","next.config.mjs"].find(f=>fs.existsSync(f));if(!f||!fs.readFileSync(f,"utf8").includes("standalone"))throw Error("STANDALONE_CONFIG_NOT_FOUND; live unchanged");'
node scripts/test-curated-common.cjs
node scripts/test-author-status.cjs
node scripts/test-free-curated-timeline.cjs
node scripts/test-fx-curated-patrol.cjs
node scripts/test-patrol-continuation.cjs
node scripts/test-monitor-jitter.cjs
node scripts/test-x-curated-hybrid.cjs
node scripts/test-free-curated-dashboard.cjs
node scripts/test-free-curated-production.cjs
node scripts/test-availability-monitor.cjs
node scripts/test-availability-curated-regression.cjs
node scripts/test-monitor-state-isolation.cjs
node scripts/test-free-curated-cursors.cjs
node scripts/test-ranking-liquidity-route.cjs
node scripts/test-newest500.cjs
node scripts/test-newest500-pages.cjs
node scripts/test-direct-download.cjs
node scripts/test-stream-component.cjs
node node_modules/typescript/bin/tsc --noEmit
npm run build > "$STAGE/build.log" 2>&1 || { echo "BUILD_FAILED; inspect $STAGE/build.log locally. Public site unchanged."; exit 1; }
cp -a .next/standalone/. "$STAGE/runtime/"
mkdir -p "$STAGE/runtime/.next"
cp -a .next/static "$STAGE/runtime/.next/static"
[[ ! -d public ]] || cp -a public "$STAGE/runtime/public"
cp "$LIVE/.env.production" "$STAGE/runtime/.env.production"
chmod 600 "$STAGE/runtime/.env.production"
mkdir -p "$STAGE/runtime/public"
for marker in "$LIVE"/public/xclip-*-version-*.txt; do [[ ! -f "$marker" ]] || cp "$marker" "$STAGE/runtime/public/"; done
VERSION=xclip-newest500-v2-version-20261013.txt
BUILD_ID=$(cat .next/BUILD_ID)
printf '%s\n' "$BUILD_ID" > "$STAGE/runtime/DEPLOY_COMMIT"
printf '%s\n' "$STAGE/source" > "$STAGE/runtime/DEPLOY_SOURCE"
printf '%s\n' "$BUILD_ID" > "$STAGE/runtime/public/$VERSION"
cd "$STAGE/runtime"
PORT=$(node -e 'const s=require("net").createServer();s.listen(0,"127.0.0.1",()=>{console.log(s.address().port);s.close();});')
PORT="$PORT" HOSTNAME=127.0.0.1 NODE_ENV=production "$NODE" server.js > "$STAGE/staging-check.log" 2>&1 &
CHECK_PID=$!

READY=0
for attempt in $(seq 1 40); do
 CODE=$(curl -sS --connect-timeout 1 --max-time 3 -o /dev/null -w '%{http_code}' "http://127.0.0.1:$PORT/download" 2>/dev/null) || CODE=000
 if [[ "$CODE" == 200 ]]; then READY=1; break; fi
 kill -0 "$CHECK_PID" 2>/dev/null || { echo 'STAGING_SERVER_EXITED; live unchanged'; exit 1; }
 sleep 1
done
[[ "$READY" == 1 ]] || { echo 'STAGING_START_TIMEOUT; live unchanged'; exit 1; }
BASE="http://127.0.0.1:$PORT" "$NODE" --env-file="$LIVE/.env.production" "$STAGE/installer/verify-endpoints.cjs"
kill "$CHECK_PID" 2>/dev/null || true
wait "$CHECK_PID" 2>/dev/null || true
CHECK_PID=''
BACKUP_BASE=$(mktemp -d "$ACCOUNT/xclip-before-newest500-20261013-v2.XXXXXX")
BACKUP="$BACKUP_BASE/runtime"
stop_cwd() {
 local root="$1" pid
 for pid in $(ps -u rbxfxmfd -o pid=,comm= | awk '$2 ~ /^(next-server|node)/ {print $1}'); do
  if [[ "$(readlink "/proc/$pid/cwd")" == "$root" ]]; then kill -TERM "$pid" 2>/dev/null || true; fi
 done
}
rollback() {
 trap - ERR INT TERM
 echo 'NEWEST500_DEPLOYMENT_FAILED; restoring previous runtime; settings unchanged'
 set +e
 if [[ -d "$BACKUP" ]]; then
  if [[ -d "$LIVE" ]]; then stop_cwd "$LIVE"; mv "$LIVE" "$BACKUP_BASE/unverified-runtime" || { echo 'ROLLBACK_MOVE_FAILED'; exit 1; }; fi
  mv "$BACKUP" "$LIVE" || { echo 'ROLLBACK_RUNTIME_RESTORE_FAILED'; exit 1; }
  mkdir -p "$LIVE/tmp"; touch "$LIVE/tmp/restart.txt"
 fi
 printf 'ROLLBACK_BACKUP=%s\n' "$BACKUP_BASE"
 local recovered=0 home_code daily_code
 for attempt in $(seq 1 15); do
  home_code=$(curl -sS --connect-timeout 5 --max-time 15 -o /dev/null -w '%{http_code}' "https://xcliprank.com/?rollback=$(date +%s)-$attempt") || home_code=000
  daily_code=$(curl -sS --connect-timeout 5 --max-time 15 -o /dev/null -w '%{http_code}' "https://xcliprank.com/ranking/daily?rollback=$(date +%s)-$attempt") || daily_code=000
  printf 'ROLLBACK_HEALTH_ATTEMPT=%s TOP_HTTP=%s DAILY_HTTP=%s\n' "$attempt" "$home_code" "$daily_code"
  if [[ "$home_code" == 200 && "$daily_code" == 200 ]]; then recovered=1; break; fi
  sleep 2
 done
 if [[ "$recovered" == 1 ]]; then echo 'ROLLBACK_PUBLIC_HEALTH_OK'; else echo 'ROLLBACK_PUBLIC_HEALTH_FAILED; share output for recovery'; fi
 echo 'PREVIOUS_RUNTIME_RESTORED; prior playback/download behavior applies'
 exit 1
}
# Last checks are read-only. Preserve concurrent changes rather than overwriting them.
[[ "$(stat -c %d "$LIVE")" == "$(stat -c %d "$STAGE/runtime")" ]] || { echo 'FILESYSTEM_MISMATCH; live unchanged'; exit 1; }
[[ "$(cat "$LIVE/.next/BUILD_ID")" == "$LIVE_BUILD_ID" ]] || { echo 'LIVE_BUILD_CHANGED_DURING_STAGING; live unchanged'; exit 1; }
cmp -s "$LIVE/.env.production" "$STAGE/source/.env.production" || { echo 'LIVE_ENV_CHANGED_DURING_STAGING; live unchanged'; exit 1; }
[[ "$(sha256sum "$HTACCESS" | cut -d ' ' -f 1)" == "$HTACCESS_INITIAL_HASH" && "$(stat -c %a "$HTACCESS")" == 644 ]] || { echo 'HTACCESS_CHANGED_DURING_STAGING; live unchanged'; exit 1; }
SOURCE="$SOURCE" "$NODE" <<'SOURCE_GUARD'
