SOURCE_GUARD
# Prevent a background worker from observing a partially switched runtime.
exec 7> "$ACCOUNT/.xclip-author-monitor.lock"
flock -n 7 || { echo 'AVAILABILITY_WORKER_BUSY; live unchanged; retry after it completes'; exit 1; }
exec 8> "$ACCOUNT/.xclip-free-curated-collector.lock"
flock -n 8 || { echo 'COLLECTOR_BUSY; live unchanged; retry after it completes'; exit 1; }
trap rollback ERR INT TERM
mv "$LIVE" "$BACKUP"
mv "$STAGE/runtime" "$LIVE"
mkdir -p "$LIVE/tmp"; touch "$LIVE/tmp/restart.txt"
stop_cwd "$BACKUP"
printf 'PREVIOUS_RUNTIME_BACKUP=%s\nACTIVATED_APP_ROOT=%s\n' "$BACKUP" "$LIVE"
VERIFIED=0
for attempt in $(seq 1 20); do
 CODE=$(curl -sS --connect-timeout 10 --max-time 20 -H 'Cache-Control: no-cache' -o "$STAGE/public-version.txt" -w '%{http_code}' "https://xcliprank.com/$VERSION?check=$(date +%s)-$attempt") || CODE=000
 printf 'PUBLIC_DIRECT_STREAM_VERSION_ATTEMPT=%s HTTP=%s\n' "$attempt" "$CODE"
 if [[ "$CODE" == 200 ]] && cmp -s "$LIVE/DEPLOY_COMMIT" "$STAGE/public-version.txt"; then VERIFIED=1; break; fi
 sleep 2
 done
[[ "$VERIFIED" == 1 ]] || rollback
BASE=https://xcliprank.com "$NODE" --env-file="$LIVE/.env.production" "$STAGE/installer/verify-endpoints.cjs"
flock -u 8
flock -u 7
trap - ERR INT TERM
echo 'XCLIP_NEWEST500_V2_DEPLOYMENT_COMPLETE'
echo 'NEWEST_TARGET=500; PAGE_SIZE=50; DAILY_WEEKLY_OVERLAP=0; AUTHOR_SPREAD=WITHIN_PAGE'
echo 'PATROL_CRON_PROVIDER_QUOTA_CURSORS_ENV_DB_SCHEMA=UNCHANGED'
echo 'NEXT=Apply optional local preview update, restart, and check homepage plus next page'
